package com.finflow.payment; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.web.bind.annotation.*; import java.math.*; import java.util.*; @RestController @RequestMapping("/api/v1/payments") class PaymentController{private final PaymentService s;PaymentController(PaymentService s){this.s=s;}record Req(@NotNull UUID sourceAccountId,@NotNull UUID destinationAccountId,@NotNull @DecimalMin("0.01") BigDecimal amount,@Pattern(regexp="[A-Z]{3}")String currency){}@PostMapping PaymentService.View create(@RequestHeader("Idempotency-Key")String key,@Valid @RequestBody Req r){return s.create(key,new PaymentService.Cmd(r.sourceAccountId,r.destinationAccountId,r.amount,r.currency));}@GetMapping("/{id}")Map<String,Object> get(@PathVariable UUID id){var p=s.get(id);return Map.of("id",p.id,"status",p.status,"amount",p.amount,"currency",p.currency);}}